const ctx = $('Resolve Context').first().json;
const pageTitle = ctx.page_title || 'WhatsFresh';
const accountName = ctx.account_name || '';
const firstName = ctx.first_name || '';
const helpText = ctx.help_text || '';

const actions = {
  click: [
    { action: 'clearvals', context_keys: ['account_id', 'first_name'] },
    { action: 'redirect', redirectUrl: '/login' }
  ]
};

const feedbackActions = {
  click: { action: 'open_pop_modal', form_template: 'feedback_form', page_id: 102 }
};

const helpActions = {
  click: { action: 'show_help' }
};

const html = `<div class="appbar" id="appbar" data-actions='${JSON.stringify(actions)}'>`
  + `<img src="/wf-icon.png" alt="WhatsFresh" class="icon">`
  + `<button id="feedback_btn" class="feedback-btn" data-actions='${JSON.stringify(feedbackActions)}'>Feedback</button>`
  + `<div class="appbar-center">`
  + (accountName ? `<span class="account-name">${accountName}</span>` : '')
  + `<span class="title">${pageTitle}`
  + (helpText ? `<button id="help_btn" class="help-btn" title="Help for this page" data-actions='${JSON.stringify(helpActions)}'>?</button>` : '')
  + `</span>`
  + `</div>`
  + (firstName ? `<span class="first-name">${firstName}</span>` : '')
  + `<button id="logout_btn" class="logout-btn" data-trigger="click">Log Out</button>`
  + (helpText ? `<template id="page_help_content">${helpText}</template>` : '')
  + `</div>`;

return [{ json: { html } }];
